    media_type_mismatch:'素材类型不符合',source_too_short:'可用区间过短',source_too_long:'超过允许源区间时长',duration_unavailable:'没有可用时长',orientation_mismatch:'画幅方向不符合',required_metadata_missing:'缺少必要分析数据',excluded_tag_present:'含明确排除标签',
