  function reason(code){const [prefix,...rest]=String(code).split(':'),value=rest.join(':');if(prefix==='visual_unverified')return (visualLabels[value]||value)+'尚无内容标注';if(prefix==='visual_description_differs')return (visualLabels[value]||value)+'描述不同，需人工比较';if(prefix==='visual_mismatch')return (visualLabels[value]||value)+'与已有标注明确不同';if(prefix==='user_semantic_matches')return '用户标注的'+(visualLabels[value]||value)+'一致';if(prefix==='required_tag_unverified')return '要求标签尚未证实：'+value;if(prefix==='user_tag_matches')return '用户标签符合：'+value;return reasons[code]||code;}
  function choices(report,source){const previous=new Map((source?.content?.choices||[]).map(row=>[row.shot_id,row]));return report.result.items.map(item=>{const old=previous.get(item.shot_id);return {shot_id:item.shot_id,mode:old?.binding?'keep':old?.mode==='reshoot'?'reshoot':'unassigned',candidate_id:null,locked:Boolean(old?.binding&&old.locked),reviewed:Boolean(old?.binding?.reviewed),note:old?.note||''};});}
  function sourceBody(report,source,rows,removedUnlocks=[],allowReuse=false){const previous=source?.content?.choices||[],current=new Map(rows.map(row=>[row.shot_id,row]));if(rows.length!==report.result.items.length||new Set(rows.map(row=>row.shot_id)).size!==rows.length)throw Error('每个镜头须有一个明确决定');const unlocks=previous.filter(row=>row.locked&&current.has(row.shot_id)&&!current.get(row.shot_id).locked).map(row=>row.shot_id);return {report_id:report.id,base_revision_id:source?.revision_id||null,choices:copy(rows),unlock_shot_ids:[...new Set([...unlocks,...removedUnlocks])],allow_reuse:Boolean(allowReuse)};}
