  function choiceView(row,previous){return row?.mode==='keep'?{...row,reviewed:Boolean(previous?.binding?.reviewed)}:row;}
  function decisionText(row,previous,item){if(row?.mode==='keep')return previous?.requirement_hash!==item.requirement_hash?'原来源不适配新需求，须解锁并重选':previous?.binding?.reviewed?'保留已采用素材（已记录人工核对）':'保留已采用素材';if(row?.mode==='candidate')return '本机已选候选，待保存';if(row?.mode==='reshoot')return previous?.mode==='reshoot'?'已保存补拍决定':'本机已选补拍，待保存';return '保留素材缺口';}
